instruction:
Refactor this code by replacing the bare except with specific, typed handling:

def parse_port(s):
    try:
        return int(s)
    except:
        return None

output:
class ConfigError(ValueError):
    pass

def parse_port(s):
    try:
        return int(s)
    except (TypeError, ValueError) as e:
        raise ConfigError(f'invalid port: {s!r}') from e

What changed: a bare except became a typed ConfigError chained to the original; callers can catch config problems without catching KeyboardInterrupt.

instruction:
Refactor this code by replacing the None-on-failure pattern with an exception:

def get_user(uid):
    row = db.find(uid)
    if row is None:
        return None
    return row

def handle(uid):
    u = get_user(uid)
    if u is None:
        return {'error': 'user lookup failed'}
    return {'name': u['name']}

output:
class UserNotFound(LookupError):
    def __init__(self, uid):
        self.uid = uid
        super().__init__(f'user {uid} not found')

def get_user(uid):
    row = db.find(uid)
    if row is None:
        raise UserNotFound(uid)
    return row

def handle(uid):
    u = get_user(uid)
    return {'name': u['name']}

What changed: failure is an exception with the uid attached; the happy path no longer carries an error branch that every caller forgets.

instruction:
Refactor this code by removing sys.exit from library code:

def load_config(path):
    try:
        with open(path) as f:
            return json.load(f)
    except IOError:
        print('cannot open ' + path)
        sys.exit(1)

output:
class ConfigError(Exception):
    pass

def load_config(path):
    try:
        with open(path) as f:
            return json.load(f)
    except OSError as e:
        raise ConfigError(f'cannot open {path}') from e

# only the CLI entry point may exit:
def main():
    try:
        cfg = load_config('config.json')
    except ConfigError as e:
        print(e)
        return 1
    return 0

What changed: the library raises ConfigError and only main() decides to exit, so the loader is testable and reusable in notebooks/services.

instruction:
Refactor this code by collecting failures instead of swallowing them per item:

def import_rows(rows):
    for r in rows:
        try:
            db.insert(r)
        except Exception:
            pass

output:
class BatchImportError(RuntimeError):
    def __init__(self, failures):
        self.failures = failures
        super().__init__(f'{len(failures)} rows failed: {failures[:3]}')

def import_rows(rows):
    failures = []
    for i, r in enumerate(rows):
        try:
            db.insert(r)
        except Exception as e:
            failures.append((i, e))
    if failures:
        raise BatchImportError(failures)

What changed: swallowed per-row errors are gathered and raised once as BatchImportError, carrying the failed indices for repair.

instruction:
Refactor this code by replacing string error codes with an exception hierarchy:

def withdraw(amount):
    if amount <= 0:
        return 'ERR_BAD_AMOUNT'
    if amount > balance:
        return 'ERR_INSUFFICIENT'
    balance -= amount
    return 'OK'

def transfer(amount, target):
    r = withdraw(amount)
    if r != 'OK':
        return r
    credit(target, amount)
    return 'OK'

output:
class BankingError(Exception):
    pass
class BadAmount(BankingError):
    pass
class InsufficientFunds(BankingError):
    def __init__(self, amount, balance):
        super().__init__(f'need {amount}, have {balance}')

def withdraw(amount):
    if amount <= 0:
        raise BadAmount(amount)
    if amount > balance:
        raise InsufficientFunds(amount, balance)
    global balance
    balance -= amount

def transfer(amount, target):
    withdraw(amount)
    credit(target, amount)

What changed: magic strings became a small exception hierarchy; callers catch InsufficientFunds specifically and messages carry real numbers.

