Refactor this code by converting the error-first callback style to exceptions:

function loadUser(id, cb) {
  db.find(id, (err, user) => {
    if (err) { cb(err); return; }
    if (!user) { cb(new Error('missing')); return; }
    cb(null, user.name);
  });
}

output:
async function loadUser(id) {
  const user = await db.find(id);
  if (!user) throw new Error('missing');
  return user.name;
}

try {
  console.log(await loadUser(7));
} catch (err) {
  console.error('failed', err);
}

What changed: two nested callbacks and manual error propagation became plain throws with a single try/catch at the edge.

