Refactor this code by removing the nested except that loses the original error:

def save(record):
    try:
        db.insert(record)
    except Exception as e:
        try:
            raise StorageError(str(e))
        except StorageError:
            pass
    return True

output:
class StorageError(RuntimeError):
    pass

def save(record):
    try:
        db.insert(record)
    except StorageError:
        raise
    except Exception as e:
        raise StorageError(f'could not insert {record.get("id")}') from e

What changed: one except with `from e` replaces the nested raise-and-swallow; StorageError only wraps what it does not already own.

instruction:
Refactor this code by giving the custom exception a proper message contract:

class MyError(Exception):
    pass

def process(step, payload):
    if payload is None:
        raise MyError('step ' + step + ' failed')
    return run(step, payload)

output:
class ProcessError(RuntimeError):
    def __init__(self, step, cause=None):
        self.step = step
        self.cause = cause
        msg = f'processing step {step!r} failed'
        if cause:
            msg += f': {cause}'
        super().__init__(msg)

def process(step, payload):
    if payload is None:
        raise ProcessError(step)
    return run(step, payload)

What changed: the exception carries `step` and `cause` as attributes and builds its message centrally, so handlers can inspect failures without string parsing.

